export function assertVisitEditable(visit){if(!visit)fail('Consulta não encontrada.');if(visit.status==='concluido'||visit.lockedAt)fail('Consulta concluída. Preserve o registro e acrescente um adendo.');if(visit.status==='cancelado'||visit.cancelledAt)fail('Consulta cancelada. Revise o estado antes de continuar.');return visit;}
export function visitMarkings(visit){return Object.entries(visit.maps||{}).flatMap(([photoId,map])=>(map.points||[]).filter(point=>point.quantity!==null&&point.quantity!==undefined).map(point=>({photoId,pointId:point.id,region:point.region,product:point.product,quantity:point.quantity,unit:point.unit})));}
// Documentos obrigatórios não são inferidos de especialidade. Integração fornece IDs efetivamente
// verificados dentro do commit pela função documentCheck(state,visit,requiredIds).
export function completeVisit(state,input,{documentCheck}={}){return atomic(state,s=>operation(s,input,'visit-completion',{visitId:input.visitId,procedureId:input.procedureId,consumptions:input.consumptions||[],quoteId:input.quoteId||'',itemId:input.itemId||'',sessions:input.sessions||1},now=>{
  const visit=assertVisitEditable(requireItem(s.visits,input.visitId,'Consulta'));requirePatient(s,visit.patientId);const today=validDate(input.today);if(validDate(visit.date)>today)fail('Uma consulta futura não pode ser concluída hoje.');const appointment=(s.appointments||[]).find(a=>a.id===visit.appointmentId);if(appointment&&(appointment.status==='cancelado'||appointment.cancelledAt))fail('O agendamento foi cancelado. Revise o estado antes de concluir.');if(appointment&&appointment.patientId!==visit.patientId)fail('O agendamento está vinculado a outra paciente.');
  const currentProcedure=active(requireItem(s.procedures,input.procedureId,'Procedimento'));
  // The visit owns the version selected at creation. A catalog edit must not silently
  // replace its price, cost, document requirements, record mode or return interval.
  const selectedProcedure=visit.procedureSnapshot;
  if(selectedProcedure&&(selectedProcedure.id!==input.procedureId||visit.procedureId!==input.procedureId||selectedProcedure.version!==visit.procedureVersion))fail('O procedimento difere da versão selecionada nesta consulta. Revise o registro antes de concluir.');
  const procedure=selectedProcedure?active(clone(selectedProcedure)):active(currentProcedure);
  const requiredDocuments=procedureDocumentIds(procedure);if(requiredDocuments.length){if(typeof documentCheck!=='function')fail('Há documentos obrigatórios configurados. Verifique-os antes de concluir.');if(documentCheck(s,visit,clone(requiredDocuments))!==true)fail('Documentos obrigatórios pendentes.');}
  const consumptions=input.consumptions||[];if(!Array.isArray(consumptions)||consumptions.length>400)fail('Consumos inválidos.');const required=visitMarkings(visit),seen=new Set(),totals=new Map();
  const usage=allocateLotCosts(consumptions.map((entry,index)=>{const lot=requireItem(s.stockLots,entry.lotId,'Lote'),product=active(requireItem(s.products,lot.productId,'Produto'));if(lot.expiry<today)fail(`Lote ${lot.code} vencido. Escolha um lote válido.`);if(lot.unit!==product.unit)fail('Unidade de lote incompatível.');const units=stockUnits(entry.quantity);let marking=null;if(entry.photoId||entry.pointId){const key=JSON.stringify([entry.photoId,entry.pointId]);if(seen.has(key))fail('A mesma marcação foi vinculada duas vezes.');seen.add(key);marking=required.find(x=>x.photoId===entry.photoId&&x.pointId===entry.pointId)||fail('Marcação de consumo não encontrada.');if(stockUnits(marking.quantity)!==units||marking.unit!==lot.unit)fail('Quantidade ou unidade do lote difere da marcação.');}totals.set(lot.id,(totals.get(lot.id)||0)+units);return{...entry,id:input.operationId+':use:'+index,lotId:lot.id,lotCode:lot.code,expiry:lot.expiry,productId:product.id,productName:product.name,unit:lot.unit,units,quantity:stockQuantity(units),unitCost:lot.unitCost,region:marking?.region||text(entry.reason,300,'o uso do material')};}));
  for(const marking of required)if(!seen.has(JSON.stringify([marking.photoId,marking.pointId])))fail('Vincule um lote a cada marcação com quantidade.');
  for(const [lotId,units] of totals){const lot=requireItem(s.stockLots,lotId,'Lote');if(lot.balanceUnits<units)fail(`Saldo insuficiente no lote ${lot.code}.`);}
  let quote=null,quoteItem=null;const sessions=integer(input.sessions??1,1,1000,'Sessões');
  if(input.quoteId){quote=requireItem(s.quotes,input.quoteId,'Orçamento');if(quote.status!=='aprovado'||quote.patientId!==visit.patientId)fail('Escolha um orçamento aprovado desta paciente.');quoteItem=requireItem(quote.items,input.itemId,'Item do orçamento');if(quoteItem.type==='product')fail('Produto não pode ser utilizado como sessão.');if(quoteItem.procedureId!==procedure.id)fail('Procedimento diferente do item aprovado.');if(remainingSessions(s,quote.id,quoteItem.id)<sessions)fail('Não há sessões suficientes na proposta.');if(s.quoteSessionUses.some(x=>x.visitId===visit.id&&!x.reversedAt))fail('A consulta já consumiu uma sessão.');}
  else if(sessions!==1)fail('Múltiplas sessões exigem orçamento vinculado.');
  const materialCost=usage.reduce((n,x)=>n+x.cost,0),actualCost=money(materialCost+procedure.cost*sessions),visitBills=(s.bills||[]).filter(b=>b.visitId===visit.id&&!b.cancelledAt);let bill;
  if(quote){bill=requireItem(s.bills,quote.billId,'Cobrança da proposta');if(bill.cancelledAt||bill.patientId!==visit.patientId||bill.total!==quote.total||bill.quoteId!==quote.id)fail('Cobrança da proposta incompatível. Revise o financeiro.');if(visitBills.some(b=>b.id!==bill.id))fail('A consulta já possui outra cobrança. Reconcilie antes de vincular o orçamento.');}
  else {if(visitBills.length>1)fail('A consulta tem cobranças múltiplas. Reconcilie o financeiro.');bill=visitBills[0];if(bill&&(bill.patientId!==visit.patientId||bill.total!==procedure.price||bill.quoteId))fail('A cobrança existente é incompatível com o procedimento. Corrija o vínculo financeiro antes de concluir.');if(!bill){bill={id:input.operationId+':bill',patientId:visit.patientId,visitId:visit.id,date:visit.date,description:procedure.name,total:procedure.price,cost:actualCost,costKind:'realizado'};s.bills.push(bill);}}
  const received=(s.payments||[]).filter(p=>p.billId===bill.id&&!p.reversedAt).reduce((n,p)=>n+p.amount,0);if(received>bill.total||received<0)fail('Recebimentos incompatíveis com a cobrança. Revise o financeiro.');
  for(const [lotId,units] of totals){const lot=requireItem(s.stockLots,lotId,'Lote');lot.balanceUnits-=units;lot.version++;s.stockMovements.push({id:input.operationId+':stock:'+lot.id,operationId:input.operationId,visitId:visit.id,lotId:lot.id,productId:lot.productId,type:'consumo',deltaUnits:-units,balanceAfter:lot.balanceUnits,unitCost:lot.unitCost,reason:'Conclusão da consulta',createdAt:now});}
  if(quote){s.quoteSessionUses.push({id:input.operationId+':session',operationId:input.operationId,quoteId:quote.id,itemId:quoteItem.id,visitId:visit.id,patientId:visit.patientId,sessions,cost:actualCost,createdAt:now});bill.actualCost=money((bill.actualCost||0)+actualCost);const pendingProducts=quote.items.filter(x=>x.type==='product'),remainingCost=quote.items.reduce((n,x)=>n+(x.type==='product'?validateQuoteItem(x).cost:remainingSessions(s,quote.id,x.id)*x.unitCost),0),complete=!pendingProducts.length&&quote.items.every(x=>remainingSessions(s,quote.id,x.id)===0);bill.cost=money(bill.actualCost+remainingCost);bill.costKind=complete?'realizado':'realizado + estimado';}
  else {bill.cost=actualCost;bill.actualCost=actualCost;bill.costKind='realizado';}
  visit.procedureId=procedure.id;visit.procedureVersion=procedure.version;visit.procedureSnapshot=clone(procedure);visit.recordMode=procedure.recordMode||'injectable';visit.status='concluido';visit.lockedAt=now;visit.completedAt=now;visit.completionOperationId=input.operationId;visit.billId=bill.id;visit.quoteId=quote?.id||null;visit.consumptions=usage;visit.actualCost=actualCost;visit.addenda=visit.addenda||[];
  visit.completionSnapshot={patientId:visit.patientId,date:visit.date,service:visit.service,notes:visit.notes,photos:clone(visit.photos||[]),maps:clone(visit.maps||{}),procedure:clone(procedure),consumptions:clone(usage),actualCost,billId:bill.id,quoteId:quote?.id||null,sessions};
  if(appointment){appointment.status='concluido';for(const expected of s.expectedReturns)if(expected.appointmentId===appointment.id&&expected.status==='agendado')expected.status='concluido';}
  const returnDate=procedureReturnDate(visit.date,procedure);if(returnDate){const rule=procedureReturnRule(procedure);s.expectedReturns.push({id:input.operationId+':return',patientId:visit.patientId,visitId:visit.id,sourceVisitId:visit.id,procedureId:procedure.id,date:returnDate,days:Math.round((Date.parse(returnDate+'T12:00:00Z')-Date.parse(visit.date+'T12:00:00Z'))/86400000),returnInterval:rule.interval,returnUnit:rule.unit,status:'previsto',createdAt:now,operationId:input.operationId});}
  return{visitId:visit.id,billId:bill.id,actualCost,materialCost,returnDate};
}));}
export function addVisitAddendum(state,input){return atomic(state,s=>operation(s,input,'visit-addendum',{visitId:input.visitId,text:input.text},now=>{const visit=requireItem(s.visits,input.visitId,'Consulta');if(visit.status!=='concluido')fail('Use o registro da consulta enquanto ela estiver em aberto.');const addendum={id:input.operationId,createdAt:now,text:text(input.text,8000,'o adendo'),kind:'adendo-local'};visit.addenda=visit.addenda||[];visit.addenda.push(addendum);return addendum;}));}
